import{_ as a,o as c,c as t,a3 as r}from"./chunks/framework.Ch_0qWu9.js";const b=JSON.parse('{"title":"Graphviz 对应源码提供声明","description":"","frontmatter":{"sourcePath":"docs/environments/lean-base/graphviz-epl/SOURCE-OFFER.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/environments/lean-base/graphviz-epl/SOURCE-OFFER.zh-CN.md","alternateUrl":"/TCSExam/docs/environments/lean-base/graphviz-epl/SOURCE-OFFER/","alternateAnchors":{"graphviz-对应源码提供声明":"graphviz-corresponding-source-offer","完整源码归档":"complete-source-archives","修改与构建规则":"modifications-and-build-rules","验证":"verification","graphviz-corresponding-source-offer":"graphviz-corresponding-source-offer","complete-source-archives":"complete-source-archives","modifications-and-build-rules":"modifications-and-build-rules","verification":"verification"}},"headers":[],"relativePath":"zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md","filePath":"zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md"}'),d={name:"zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md"};function i(o,e,s,p,h,n){return c(),t("div",null,[...e[0]||(e[0]=[r(`<p><a id="graphviz-corresponding-source-offer"></a></p><h1 id="graphviz-对应源码提供声明" tabindex="-1">Graphviz 对应源码提供声明 <a class="header-anchor" href="#graphviz-对应源码提供声明" aria-label="Permalink to &quot;Graphviz 对应源码提供声明&quot;">​</a></h1><p>中文译文供参考，许可条款以原文为准。</p><p>ProofWidgets 浏览器代码中嵌入的 Graphviz 15.0.0 程序以 EPL-2.0 提供。Graphviz 完整对应源码、固定封装层源码、封装层对 Graphviz 的修改和构建规则随镜像保存在 <code>/usr/share/doc/tcsexam/graphviz-epl/</code> 下。接收者可直接从该目录获取这些源码材料，无需网络访问。</p><p><a id="complete-source-archives"></a></p><h2 id="完整源码归档" tabindex="-1">完整源码归档 <a class="header-anchor" href="#完整源码归档" aria-label="Permalink to &quot;完整源码归档&quot;">​</a></h2><p>读法说明：每行列出一个组件的安装归档、官方来源、大小和已验证哈希值。</p><table tabindex="0"><thead><tr><th>组件</th><th>已安装归档</th><th>官方来源</th><th style="text-align:right;">字节数</th><th>已验证 SHA-256</th></tr></thead><tbody><tr><td>Graphviz 15.0.0</td><td><code>source/graphviz-15.0.0.tar.gz</code></td><td><a href="https://gitlab.com/graphviz/graphviz/-/archive/15.0.0/graphviz-15.0.0.tar.gz" target="_blank" rel="noreferrer">https://gitlab.com/graphviz/graphviz/-/archive/15.0.0/graphviz-15.0.0.tar.gz</a></td><td style="text-align:right;">41113527</td><td><code>dfa5be5c311f760aa9c88273c8f8101bb11f50b0de8b29bbd54acff3adc2d563</code></td></tr><tr><td><code>hpcc-js-wasm</code> 提交 <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code></td><td><code>source/hpcc-js-wasm-8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz</code></td><td><a href="https://github.com/hpcc-systems/hpcc-js-wasm/archive/8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz" target="_blank" rel="noreferrer">https://github.com/hpcc-systems/hpcc-js-wasm/archive/8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz</a></td><td style="text-align:right;">455080</td><td><code>5443207dda2c30581e0632c8add206fcae3906f5faf20d4a0808499934743ee6</code></td></tr></tbody></table><p>Graphviz 归档的 SHA-512 为 <code>d69e2dd7b5127650b6e09de92508a84886d52d5dfd1eacf9e6abb797ca231db3c1b12546c7b8561e311150cd62be8dfea689021b7d139ffcdb3d4e16da670352</code>，与封装层 <code>vcpkg-overlays/graphviz/portfile.cmake</code> 中固定的值完全一致。封装层归档的 SHA-512 为 <code>1a195429ba1d9d47803a78fc700c601ffcbd340d42b3c753f0f2a77cec4782768844b658227543bad7597ea5af553590c401a25ccc1aefea31a6b04f19e16a63</code>。</p><p>源码准备命令根据声明的大小和哈希值验证完整归档。Graphviz 中的 <code>LICENSE</code> 文件安装为 <code>EPL-2.0.txt</code>；封装层中的 <code>LICENSE</code> 文件安装为 <code>WRAPPER-APACHE-2.0.txt</code>。</p><p><a id="modifications-and-build-rules"></a></p><h2 id="修改与构建规则" tabindex="-1">修改与构建规则 <a class="header-anchor" href="#修改与构建规则" aria-label="Permalink to &quot;修改与构建规则&quot;">​</a></h2><p>封装层归档是 <code>@hpcc-js/wasm</code> 2.34.2 的固定源码。npm 版本元数据将提交 <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code> 标为其 <code>gitHead</code>。</p><p>封装层的 <code>vcpkg-overlays/graphviz/portfile.cmake</code> 使用 overlay 内的文件替换 Graphviz 顶层的 <code>CMakeLists.txt</code> 和 <code>cmake/config_checks.cmake</code>。它还替换该 portfile 中说明的 <code>GVPLUGIN_CURRENT</code> 和 <code>GVPLUGIN_REVISION</code> 替换项。具体文件既保存在封装层归档中，也以可读副本形式保存在 <code>build-rules/vcpkg-overlays/graphviz/</code> 下。</p><p>封装层 C++ 入口和支持源码位于 <code>build-rules/packages/graphviz/src-cpp/</code>。封装层构建文件选择 Emscripten SDK 6.0.0 和 vcpkg 2026.06.01。它们的官方项目位置为：</p><ul><li><a href="https://github.com/emscripten-core/emsdk" target="_blank" rel="noreferrer">https://github.com/emscripten-core/emsdk</a></li><li><a href="https://github.com/microsoft/vcpkg" target="_blank" rel="noreferrer">https://github.com/microsoft/vcpkg</a></li></ul><p>从源码重建时，将封装层归档解压到可写目录，并遵循 <code>build-rules/README.md</code>。该固定源码记录的主要命令为 <code>npm ci</code>、<code>npm run install-build-deps</code> 和 <code>npm run build</code>。完整归档包含构建脚本和预设。安装指定构建工具，并在这组 Graphviz 专用归档旁一并保留这些工具适用的源码及许可材料。</p><p><a id="verification"></a></p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>从安装目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/doc/tcsexam/graphviz-epl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p><code>source-manifest.json</code> 以机器可读形式记录相同的版本、官方 URL、归档大小和哈希值。镜像中其他组件的源码和声明见单独的浏览器组件及 npm 清单。</p>`,22)])])}const f=a(d,[["render",i]]);export{b as __pageData,f as default};
